import {neutral} from './pose-model.js';
import {poseGuide} from './drawing-reference.js';
// Loaded only after the explicit Find pose action. No pixels leave the browser.
// MediaPipe Tasks Vision Apache-2.0, pinned runtime and model revision.
const RUNTIME='https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14';
const MODEL='https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task';
let engine=null;
export function landmarkGuide(points){if(!Array.isArray(points)||points.length!==33||points.some(p=>!p||!Number.isFinite(p.x)||!Number.isFinite(p.y)||Math.abs(p.x)>4||Math.abs(p.y)>4))throw Error('Invalid detected landmarks');const g=poseGuide(neutral()),p=i=>[points[i].x*600,points[i].y*600],mid=(a,b)=>a.map((v,i)=>(v+b[i])/2);
 const ids={leftShoulder:11,rightShoulder:12,leftElbow:13,rightElbow:14,leftWrist:15,rightWrist:16,leftHip:23,rightHip:24,leftKnee:25,rightKnee:26,leftAnkle:27,rightAnkle:28,leftToe:31,rightToe:32};for(const [id,i]of Object.entries(ids))g.joints[id]=p(i);g.joints.pelvis=mid(p(23),p(24));g.joints.chest=mid(p(11),p(12));g.joints.head=mid(p(7),p(8));g.joints.neck=mid(g.joints.chest,g.joints.head);g.provenance='MediaPipe Pose Landmarker lite · estimated joints; review against your image';return g;}
export async function detectPose(image,onProgress=()=>{}){onProgress('Downloading pose model / preparing on-device inference…');try{if(!engine){engine=(async()=>{const {FilesetResolver,PoseLandmarker}=await import(RUNTIME+'/vision_bundle.mjs'),files=await FilesetResolver.forVisionTasks(RUNTIME+'/wasm');return PoseLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:MODEL,delegate:'CPU'},runningMode:'IMAGE',numPoses:1,minPoseDetectionConfidence:.5,minPosePresenceConfidence:.5,outputSegmentationMasks:false});})();}const detector=await engine;onProgress('Finding a human pose on this device…');const result=detector.detect(image);if(!result.landmarks?.length)throw Error('No human pose found. Try a clearer full-body image, or add a pose and adjust the joints manually.');const points=result.landmarks[0];if([11,12,23,24].filter(i=>(points[i].visibility??1)<.3).length>2)throw Error('Pose confidence is too low. Use a clearer image or trace the joints manually.');return landmarkGuide(points);}catch(e){engine=null;throw Error('Pose detection: '+(e.message||'model unavailable')+'. Your image is unchanged.');}}
